  tpl: {
    note: "PSI calculator: enter the share of the population in each of 5 score bands at training time (expected) and now (actual).",
    in: [["e1", "Expected band 1 %", 20], ["e2", "Expected band 2 %", 20], ["e3", "Expected band 3 %", 20], ["e4", "Expected band 4 %", 20], ["e5", "Expected band 5 %", 20], ["a1", "Actual band 1 %", 14], ["a2", "Actual band 2 %", 18], ["a3", "Actual band 3 %", 21], ["a4", "Actual band 4 %", 22], ["a5", "Actual band 5 %", 25], ["appRef", "Approval rate reference group %", 82.1], ["appProt", "Approval rate protected group %", 75.2]],
    out: [["PSI", v => [1, 2, 3, 4, 5].reduce((s, i) => { const a = v["a" + i] / 100, e = v["e" + i] / 100; return s + (a - e) * Math.log(a / e); }, 0), "dec3", "OK < 0.10 · WATCH ≤ 0.25 · ACT > 0.25"], ["PSI band", v => { const p = [1, 2, 3, 4, 5].reduce((s, i) => { const a = v["a" + i] / 100, e = v["e" + i] / 100; return s + (a - e) * Math.log(a / e); }, 0); return p < 0.1 ? "OK" : p <= 0.25 ? "WATCH" : "ACT"; }, "text"], ["Adverse impact ratio", v => v.appProt / v.appRef, "dec2", "trigger 0.95 · floor 0.90 (4/5ths rule = 0.80)"]],
    table: { file: "monthly-monitoring-report.csv", cols: ["Use case", "Monitor", "Value this month", "Last month", "Threshold", "Status", "Action / owner"], rows: [["Credit scorecard", "PSI utilisation", "0.19", "0.14", "WATCH 0.10–0.25", "WATCH", "Investigate drift — Priya"], ["Credit scorecard", "AIR", "0.92", "0.92", "trigger 0.95", "WATCH", "Options paper to Council"], ["Policy copilot", "Golden set hit@3", "94%", "91%", "≥ 85%", "OK", "—"], ["Fraud model", "Precision @100 alerts/day", "80%", "80%", "≥ 75%", "OK", "—"]] }
  },
  f: [["PSI", "Σ (actual% − expected%) × ln(actual% ÷ expected%)", "utilisation 0.19 → WATCH", "< 0.10"], ["Adverse impact ratio", "approval rate(protected) ÷ approval rate(reference)", "75.2 ÷ 82.1 = 0.92", "≥ 0.95 internal, ≥ 0.80 legal floor"], ["Precision@k", "true frauds in top k alerts ÷ k", "@100: 80%", "per threshold memo"], ["Recall", "frauds caught ÷ all frauds", "@100: 18.8%", "per threshold memo"], ["hit@k", "queries with correct source in top k ÷ queries", "v1.4: 80% (failed 85% gate)", "≥ gate"]],
  data: [["Scoring logs", "Decision engine", "MLOps", "Daily", "Complete feature vectors"], ["Outcomes", "Collections / fraud case systems", "Business ops", "Monthly (lagged)", "Outcome window matured"], ["Protected attribute proxies", "Approved fairness dataset", "DS + Legal", "Monthly", "Approved method (e.g. BISG) documented"], ["Golden set", "Eval repo", "Eval engineer", "Per release", "Versioned; slices labelled"]],
  produce: ["Run monitors; fill the monthly report table.", "Anything WATCH → owner investigates; ACT → incident + decision.", "Golden-set run per release; gate decision recorded.", "Quarterly re-sign threshold memos."],
  pit: ["Aggregate metrics hiding slice regressions", "Drift thresholds tuned to silence", "In-sample evaluation"], where: ["Release decisions", "AI Council fairness and drift triggers", "Validation and audit"], helps: ["Problems caught before customers feel them", "Defensible fairness position", "Safer, faster releases"],
  value: "Monitoring and gates are how a bank keeps the promise it made when it approved a model. They catch drift, unfairness and regressions early — when fixing them is a retrain, not a remediation programme.",
